e.command:
$root='C:\Users\aaron\Documents\GitHub\binnacle-claude-mod'
$all = Get-ChildItem -LiteralPath $root -Recurse -Force -File -Filter *.json -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '[\\/]\.git[\\/]' }
"total: $($all.Count)"
"top: $(($all | Where-Object { $_.DirectoryName -eq $root }).Count)"
"non-node_modules:"
$all | Where-Object { $_.FullName -notmatch '[\\/]node_modules[\\/]' } | ForEach-Object { $_.FullName }
